func makeSpan() -> Span<Int> {
    let local: [3 of Int] = [1, 2, 3]
    return local.span
}

func sum(_ span: Span<Int>) -> Int {
    var total = 0
    for i in span.indices {
        total += span[i]
    }
    return total
}

func run() {
    let fixed: [3 of Int] = [5, 10, 15]
    let array = [2, 3]
    print(sum(fixed.span), sum(array.span))
}
run()

