func doubleAll(_ span: inout MutableSpan<Int>) {
    for i in span.indices {
        span[i] *= 2
    }
}

func run() {
    var nums: [3 of Int] = [3, 5, 7]
    do {
        var view = nums.mutableSpan
        doubleAll(&view)
    }
    print(nums[0], nums[2])
}
run()

