func maxInSpan(_ span: Span<Int>) -> Int? {
    guard !span.isEmpty else { return nil }
    var best = span[0]
    for i in span.indices {
        if span[i] > best { best = span[i] }
    }
    return best
}

func run() {
    let values: [3 of Int] = [4, 19, 7]
    print(maxInSpan(values.span) ?? 0)
}
run()

func zeroOut(_ span: inout MutableSpan<Int>) {
    for i in span.indices {
        span[i] = 0
    }
}

func run() {
    var buffer: [3 of Int] = [5, 8, 11]
    do {
        var view = buffer.mutableSpan
        zeroOut(&view)
    }
    print(buffer[0], buffer[2])
}
run()
